## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd2;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic        m_axis_tready = 1'b0;
  logic        rxd = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire         s_axis_tready;
  wire         txd;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         tx_busy, rx_busy, rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart #(.DATA_WIDTH(8)) dut (
    .clk(clk), .rst(rst),
    .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid), .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid), .m_axis_tready(m_axis_tready),
    .rxd(rxd), .txd(txd),
    .tx_busy(tx_busy), .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error), .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(4);
    rst = 1'b0; wait_clks(4);
  endtask

  // Drive an 8N1 frame on rxd, LSB first, each bit held prescale*8 clocks.
  task automatic uart_rx_send_byte(input logic [7:0] b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0; wait_clks(bit_clks);
    for (int i = 0; i < 8; i++) begin
      rxd = b[i]; wait_clks(bit_clks);
    end
    rxd = 1'b1; wait_clks(bit_clks);
  endtask

  initial begin
    do_reset();

    // --- Step 1: deliver 8'h3C into the FIFO with sink stalled ---
    m_axis_tready = 1'b0;
    uart_rx_send_byte(8'h3C);

    // Wait until the word is presented on the AXI bus
    wait (m_axis_tvalid && (m_axis_tdata == 8'h3C));
    @(negedge clk);

    // --- Step 2: inject a false start bit while 8'h3C is still pending ---
    // With prescale=2 the start-bit half-period is 7 clocks; a 2-clock low
    // pulse is far shorter, so the mid-start sample sees rxd_reg high and
    // the receiver aborts the frame (prescale_reg==0, bit_cnt==10, rxd_reg==1).
    rxd = 1'b0;
    wait_clks(2);
    rxd = 1'b1;
    // Give the receiver time to reject the false start and return to idle
    wait_clks(10);

    // --- Step 3: accept the pending 8'h3C word ---
    m_axis_tready = 1'b1;
    wait (!m_axis_tvalid);
    @(negedge clk);

    // --- Step 4: deliver a fresh 8'hA5 frame; coverage fires on its rising tvalid ---
    uart_rx_send_byte(8'hA5);

    wait (m_axis_tvalid && (m_axis_tdata == 8'hA5));
    @(negedge clk);

    $display("PASS R28");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
```

